export function Nota() {
  const [texto, setTexto] = useState("");

  useEffect(() => {
    console.log("Nota activa");
    return () => console.log("Nota pausada");
  }, []);

  return (
    <p>
      <label htmlFor="nota">Nota de estudio</label>
      <br />
      <textarea
        id="nota"
        value={texto}
        onChange={(evento) => setTexto(evento.target.value)}
      />
    </p>
  );
}

