#include <array>
#include <iostream>
#include <ranges>
#include "sesion.hpp"

int main() {
    const std::array sesiones{
        Sesion{"HTML", 15}, Sesion{"C++", 30},
        Sesion{"SQL", 25}, Sesion{"Java", 45}
    };

    auto temas = sesiones
        | std::views::filter([](const Sesion& sesion) {
            return sesion.minutos >= 25;
        })
        | std::views::transform(&Sesion::tema)
        | std::views::take(2);

    for (auto tema : temas) {
        std::cout << tema << '\n';
    }
}

